/*
 * @file demo-item.seed.ts
 * @description DemoItem 权限点与菜单种子（由 fw gen crud 生成，PRD-003 FR-04/FR-09）：
 *   幂等写入 4 个权限点（demo-item:create/read/update/delete）与后台菜单记录。
 *   接入方式：在 prisma/seed.ts 的 main() 中 import 并调用 seedDemoItemPermissions()，
 *   然后 pnpm db:seed；菜单变更后重新登录即生效（动态路由）。
 * @author donttemo
 * @created 2026-10-13
 * @module __APP_NAME__
 * @since v0.1.0
 * @generated by @fw/cli gen crud —— 本文件由代码生成器产出；业务扩展请勿直接修改，改用继承 / 钩子（--force 才会覆盖本文件）
 */

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

/** 权限点定义（编码规范：资源:操作，类型 api） */
const PERMISSIONS = [
  { code: 'demo-item:create', name: 'DemoItem-新建', type: 'api', module: 'demo-item' },
  { code: 'demo-item:read', name: 'DemoItem-查询', type: 'api', module: 'demo-item' },
  { code: 'demo-item:update', name: 'DemoItem-更新', type: 'api', module: 'demo-item' },
  { code: 'demo-item:delete', name: 'DemoItem-删除', type: 'api', module: 'demo-item' },
];

/** 菜单定义（component 相对 web/src，供动态路由加载） */
const MENU = {
  name: 'DemoItem管理',
  path: '/demo-items',
  component: 'views/demo-item/index',
  icon: 'List',
  permissionCode: 'demo-item:read',
  visible: 1,
  sort: 0,
};

/** 超级管理员角色码：新模块的权限必须授给它，否则登录后菜单里根本没有这一项 */
const ADMIN_ROLE_CODE = 'admin';

/**
 * 把本次生成的权限点授给超级管理员（幂等）
 * @returns 实际授予的条数（角色不存在时返回 0，不视为失败）
 * @description 只建权限点不授权，`/auth/menus` 会按用户权限码过滤掉这个菜单——用户在后台
 *   看不到刚生成的模块，只能以为「生成失败」。
 */
async function grantToAdminRole(): Promise<number> {
  // role.code 不是唯一键（多租户下可重名），只能按 code + 未删除查首条
  const role = await prisma.role.findFirst({
    where: { code: ADMIN_ROLE_CODE, deletedAt: null },
    orderBy: { createdAt: 'asc' },
  });
  if (!role) return 0;
  let granted = 0;
  for (const permission of PERMISSIONS) {
    const row = await prisma.permission.findUnique({ where: { code: permission.code } });
    if (!row) continue;
    await prisma.rolePermission.upsert({
      where: { roleId_permissionId: { roleId: role.id, permissionId: row.id } },
      create: { roleId: role.id, permissionId: row.id },
      update: {},
    });
    granted += 1;
  }
  return granted;
}

/**
 * 幂等写入DemoItem权限点与菜单
 * 权限点按 code 唯一键 upsert；菜单按 path 查重后更新或新建（可重复执行）
 */
export async function seedDemoItemPermissions(): Promise<void> {
  for (const permission of PERMISSIONS) {
    await prisma.permission.upsert({
      where: { code: permission.code },
      create: permission,
      update: permission,
    });
  }
  const existing = await prisma.menu.findFirst({ where: { path: MENU.path } });
  if (existing) {
    await prisma.menu.update({ where: { id: existing.id }, data: MENU });
  } else {
    await prisma.menu.create({ data: MENU });
  }
  const granted = await grantToAdminRole();
  console.log(
    `[seed] 已写入 DemoItem 权限点 ${PERMISSIONS.length} 个与菜单 1 条（授给 ${ADMIN_ROLE_CODE} 角色 ${granted} 条）`,
  );
}

// 允许独立执行（pnpm exec tsx prisma/seed/demo-item.seed.ts），被 seed.ts 引用时也可复用
const isDirectRun = process.argv[1]?.includes('demo-item.seed');
if (isDirectRun) {
  seedDemoItemPermissions()
    .catch((error: unknown) => {
      console.error('[seed] 失败:', error);
      process.exit(1);
    })
    .finally(() => prisma.$disconnect());
}
